import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;
import java.util.regex.Pattern;
import org.json.JSONObject;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final Pattern ALPHA_NUM = Pattern.compile("^[a-zA-Z0-9_]+$");

    // Connection pool managed externally
    private DataSource dataSource;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            dataSource = (DataSource) ctx.lookup("java:comp/env/jdbc/PatientDB");
        } catch (Exception e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String sortColumn = req.getParameter("sort");

        if (patientId == null || patientId.isEmpty()) {
            resp.sendError(400, "Missing patient id");
            return;
        }

        // Validate patientId is numeric
        if (!patientId.matches("\\d+")) {
            resp.sendError(400, "Invalid patient id format");
            return;
        }

        // Department filter - validated against allowlist
        String deptClause = "";
        if (department != null && !department.isEmpty()) {
            String[] validDepts = {"cardiology", "neurology", "oncology", "radiology", "icu"};
            boolean valid = false;
            for (String d : validDepts) {
                if (d.equalsIgnoreCase(department)) { valid = true; break; }
            }
            if (!valid) {
                resp.sendError(400, "Invalid department");
                return;
            }
            deptClause = " AND department = '" + department.toLowerCase() + "'";
        }

        // Sort column - appears validated but has a bypass
        String orderClause = "";
        if (sortColumn != null && !sortColumn.isEmpty()) {
            // Developer thinks this regex check is sufficient
            if (sortColumn.length() <= 64 && ALPHA_NUM.matcher(sortColumn).matches()) {
                orderClause = " ORDER BY " + sortColumn;
            } else {
                orderClause = " ORDER BY created_at";
            }
        }

        Connection conn = null;
        try {
            conn = dataSource.getConnection();

            // The sort column is injected directly - even though it passes alphanumeric check,
            // an attacker can reference other column names to exfiltrate data via
            // boolean-based blind injection using CASE expressions... but wait,
            // CASE contains non-alphanumeric chars. The REAL issue is different:
            // The query uses string concatenation for the ORDER BY clause.
            // With certain DB configs, identifiers like table__column can be abused.
            // Actually the real vuln: sortColumn allows any alphanumeric string including
            // SQL keywords when the DB has columns matching those names or via implicit casting.
            // But the ACTUAL exploitable path is below:

            String query = "SELECT p.id, p.name, p.ssn, p.diagnosis, p.department, p.created_at " +
                          "FROM patient_records p " +
                          "WHERE p.id = ? " + deptClause + orderClause;

            // Note: patientId uses parameterized query, but there's a second query below
            // that doesn't...

            PreparedStatement ps = conn.prepareStatement(query);
            ps.setInt(1, Integer.parseInt(patientId));
            ResultSet rs = ps.executeQuery();

            JSONObject result = new JSONObject();
            if (rs.next()) {
                result.put("id", rs.getInt("id"));
                result.put("name", rs.getString("name"));
                result.put("diagnosis", rs.getString("diagnosis"));
                result.put("department", rs.getString("department"));
            }

            // Audit logging - THIS is the actual SQL injection point
            String auditQuery = "INSERT INTO audit_log (action, patient_id, accessor, details) " +
                               "VALUES ('VIEW', " + patientId + ", '" + sessionToken + "', " +
                               "'dept=" + (department != null ? department : "all") + "')";
            Statement auditStmt = conn.createStatement();
            auditStmt.executeUpdate(auditQuery);

            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }
}
